begin read only;select jsonb_build_object('auth_identity_orphans',(select count(*)from auth.identities i where not exists(select 1 from auth.users u where u.id=i.user_id)),'auth_session_orphans',(select count(*)from auth.sessions s where s.user_id is not null and not exists(select 1 from auth.users u where u.id=s.user_id)),'storage_object_bucket_orphans',(select count(*)from storage.objects o where not exists(select 1 from storage.buckets b where b.id=o.bucket_id))) managed_integrity;rollback;
